using json=nlohmann::json;using namespace rocks;namespace fs=std::filesystem;using Clock=std::chrono::steady_clock;
static json read(const fs::path&p){std::ifstream in(p);if(!in)throw std::runtime_error("cannot read "+p.string());return json::parse(in);}
static void write(const fs::path&p,const json&j){std::ofstream out(p);out<<j.dump();if(!out)throw std::runtime_error("cannot write "+p.string());}
static std::uint32_t integer(const json&j,const char*name){if(!j.is_number_integer()||j.get<double>()<0||j.get<double>()>4294967295.)throw std::invalid_argument(std::string(name)+" must be uint32");return j.get<std::uint32_t>();}
static Recipe parse(const json&j,unsigned&cells){Recipe r; std::set<std::string> allowed={"schemaVersion","seed","units","generatorVersion","extractorVersion","size","layerThickness","contrast","wear","grid"};if(j.value("schemaVersion",0)==2){allowed.insert("family");if(j.contains("detail"))allowed.insert("detail");}if(j.value("generatorVersion",std::string{})=="rocks-v12"){allowed.insert("studySpacing");if(j.value("family",std::string{})=="columnar_basalt")for(auto key:{"columnCount","columnLean","jointDepth"})allowed.insert(key);else for(auto key:{"roundness","chipping"})allowed.insert(key);}if(!j.is_object()||j.size()!=allowed.size())throw std::invalid_argument("recipe requires exactly documented fields");for(auto &[key,v]:j.items())if(!allowed.contains(key))throw std::invalid_argument("unknown recipe key "+key);r.schemaVersion=integer(j.at("schemaVersion"),"schemaVersion");if(r.schemaVersion==2)r.family=j.at("family").get<std::string>();r.seed=integer(j.at("seed"),"seed");r.units=j.at("units").get<std::string>();r.generatorVersion=j.at("generatorVersion").get<std::string>();r.extractorVersion=j.at("extractorVersion").get<std::string>();auto number=[&](const char*k){const auto&v=j.at(k);if(!v.is_number())throw std::invalid_argument(std::string(k)+" must be number");return v.get<double>();};if(r.generatorVersion=="rocks-v12"){r.studySpacing=number("studySpacing");if(r.family=="columnar_basalt"){r.columnCount=integer(j.at("columnCount"),"columnCount");r.columnLean=number("columnLean");r.jointDepth=number("jointDepth");}else{r.roundness=number("roundness");r.chipping=number("chipping");}}r.size=number("size");r.layerThickness=number("layerThickness");r.contrast=number("contrast");r.wear=number("wear");if(j.contains("detail"))r.detail=number("detail");if(!j.at("grid").is_object()||j.at("grid").size()!=1)throw std::invalid_argument("grid requires cells only");cells=integer(j.at("grid").at("cells"),"cells");auto e=validateRecipe(r,makeGrid(r,cells));if(!e.empty())throw std::invalid_argument(e.front());return r;}
static json meshjson(const Mesh&m){json j;std::vector<double>p,n;p.reserve(m.positions.size()*3);n.reserve(m.normals.size()*3);for(auto v:m.positions)p.insert(p.end(),{v.x,v.y,v.z});for(auto v:m.normals)n.insert(n.end(),{v.x,v.y,v.z});j["positions"]=p;j["normals"]=n;j["resistance"]=m.resistance;j["indices"]=m.indices;if(!m.cornerNormals.empty()){std::vector<double> corners;for(auto v:m.cornerNormals)corners.insert(corners.end(),{v.x,v.y,v.z});j["cornerNormals"]=corners;}return j;}
static void obj(const fs::path&p,const Mesh&m){std::ofstream o(p);o<<std::setprecision(17)<<"# JericoRocksLab portable C++ mesh; Y up; meters\n";for(auto v:m.positions)o<<"v "<<v.x<<' '<<v.y<<' '<<v.z<<'\n';for(auto v:(m.cornerNormals.empty()?m.normals:m.cornerNormals))o<<"vn "<<v.x<<' '<<v.y<<' '<<v.z<<'\n';for(std::size_t i=0;i<m.indices.size();i+=3){o<<"f";for(int k=0;k<3;k++)o<<' '<<m.indices[i+k]+1<<"//"<<(m.cornerNormals.empty()?m.indices[i+k]+1:i+k+1);o<<'\n';}if(!o)throw std::runtime_error("OBJ write failed");}
static Mesh parseMesh(const json&j){Mesh m;auto p=j.at("positions").get<std::vector<double>>();if(p.size()%3)throw std::invalid_argument("invalid positions");for(std::size_t i=0;i<p.size();i+=3)m.positions.push_back({p[i],p[i+1],p[i+2]});m.indices=j.at("indices").get<std::vector<std::uint32_t>>();return m;}
static int compareCommand(int argc,char**argv){if(argc!=8||std::string(argv[2])!="--a"||std::string(argv[4])!="--b"||std::string(argv[6])!="--out")throw std::invalid_argument("usage: rocks_cli compare --a viewer.json --b viewer.json --out report.json");auto a=read(argv[3]),b=read(argv[5]);json report={{"method","bidirectional vertices and triangle centroids to nearest triangles; sampled, not Hausdorff proof"}};for(const char*n:{"base","stratified","eroded"}){auto d=compareSurfaces(parseMesh(a.at("stages").at(n)),parseMesh(b.at("stages").at(n)));report["stages"][n]={{"maxDistance",d.maxDistance},{"rmsDistance",d.rmsDistance},{"sampleCount",d.sampleCount}};}auto strat=parseMesh(b.at("stages").at("stratified"));auto eroded=parseMesh(b.at("stages").at("eroded"));auto base=parseMesh(b.at("stages").at("base"));auto wear=compareSurfaces(strat,eroded),setback=compareSurfaces(base,strat);report["geometryDisplacementAtB"]={{"baseToStructureMaxSampled",setback.maxDistance},{"structureToErodedMaxSampled",wear.maxDistance},{"structureToErodedRmsSampled",wear.rmsDistance}};write(argv[7],report);std::cout<<report.dump(2)<<'\n';return 0;}
static int heightmapCommand(int argc,char**argv){
 if(argc!=6||std::string(argv[2])!="--config"||std::string(argv[4])!="--out")throw std::invalid_argument("usage: rocks_cli heightmap-reference --config reference.json --out directory");
 const bool procedural=std::string(argv[1])=="procedural-heightfield";
 fs::path configPath=argv[3];auto config=read(configPath);HeightfieldSpec spec;spec.width=integer(config.at("width"),"width");spec.height=integer(config.at("height"),"height");spec.cells=integer(config.at("cells"),"cells");spec.size=config.at("size").get<double>();spec.relief=config.at("relief").get<double>();spec.backDepth=config.at("backDepth").get<double>();
 if(spec.width<2||spec.height<2||spec.width>4096||spec.height>4096)throw std::invalid_argument("heightmap source dimensions outside [2,4096]");
 std::size_t count=std::size_t(spec.width)*spec.height;std::vector<std::uint16_t> samples;
 if(procedural)samples=proceduralCliffHeightSamples(spec.width,spec.height,integer(config.at("seed"),"seed"),config.contains("bedCount")?integer(config.at("bedCount"),"bedCount"):5,config.value("fragmentedContacts",false));
 else{fs::path source=configPath.parent_path()/config.at("source").get<std::string>();if(fs::file_size(source)!=count*2)throw std::invalid_argument("heightmap raw sample count mismatch");std::ifstream input(source,std::ios::binary);std::vector<unsigned char> bytes(count*2);input.read(reinterpret_cast<char*>(bytes.data()),std::streamsize(bytes.size()));if(!input)throw std::runtime_error("cannot read uint16 heightmap source");samples.resize(count);for(std::size_t i=0;i<count;i++)samples[i]=std::uint16_t(bytes[2*i])|(std::uint16_t(bytes[2*i+1])<<8);}

 auto ex=heightfieldSolid(samples,spec);auto report=validate(ex.mesh,spec.size);auto mm=std::minmax_element(samples.begin(),samples.end());
 json metrics={{"sourceKind",procedural?"procedural_heightfield":"reference_heightmap"},{"description",procedural?"Procedural warped beds, plateaus and finite joints; no reference pixels used; single-valued front, no overhangs":"Heightmap-derived single-valued front with closed back/sides; not procedural geology, not overhang geometry, not physically height-calibrated"},{"sourceUrl",config.value("sourceUrl","")},{"license",config.value("license","")},{"accepted",report.accepted},{"vertices",ex.mesh.positions.size()},{"triangles",ex.mesh.indices.size()/3},{"signedVolume",report.signedVolume},{"components",report.components},{"badEdges",report.badEdges},{"badVertices",report.badVertices},{"degenerateFaces",report.degenerateFaces},{"sourceCodesMin",*mm.first},{"sourceCodesMax",*mm.second},{"normalization","observed source uint16 min/max; exact clipped box-area integration of bilinear source cells in C++"},{"gridCells",spec.cells},{"sizeMeters",spec.size},{"chosenReliefMeters",spec.relief},{"backDepthMeters",spec.backDepth},{"extractNormalsMs",ex.extractNormalsMs},{"errors",report.errors}};
 if(!report.accepted){std::cerr<<metrics.dump(2)<<'\n';return 2;}
 fs::path out=argv[5];fs::create_directories(out);obj(out/(procedural?"procedural.obj":"reference.obj"),ex.mesh);std::ofstream rawOutput(out/"height.u16",std::ios::binary);for(auto value:samples){rawOutput.put(char(value&255));rawOutput.put(char(value>>8));}if(!rawOutput)throw std::runtime_error("cannot write height samples");write(out/"mesh.json",meshjson(ex.mesh));json exported=config;if(!procedural)exported["source"]="height.u16";write(out/"configuration.json",exported);write(out/"metrics.json",metrics);std::cout<<metrics.dump(2)<<'\n';return 0;
}
static HeightfieldRecipe parseSurfaceFamily(const json&j){
 if(!j.is_object()||!j.contains("profile")||!j.at("profile").is_string())throw std::invalid_argument("surface family profile required");
 const auto profile=j.at("profile").get<std::string>();const bool limestone=profile=="limestone_dissolution",alveolar=profile=="alveolar_blocks",reference=isReferenceStudy(profile),lava=profile=="lava_rope_lobes";
 if(!reference&&!alveolar&&!limestone&&profile!="shale_laminated"&&profile!="slate_foliated")throw std::invalid_argument("unsupported surface family");
 std::set<std::string> keys={"schemaVersion","generatorVersion","extractorVersion","family","units","profile","seed","size","relief","backDepth","directionDegrees","featureDepth","fractures","irregularity","grid"};
 if(reference){if(lava)for(auto k:{"ridgeSpacingMeters","ridgeWidthMeters","lobeRadiusMeters","lobeCount"})keys.insert(k);else for(auto k:{"fragmentScaleMeters","fragmentCount"})keys.insert(k);}
 else if(alveolar)for(auto k:{"patchCount","patchRadiusMeters","alveolusRadiusMeters"})keys.insert(k);
 else if(limestone)for(auto k:{"channelSpacingMeters","channelWidthMeters","pocketRadiusMeters","pocketCount"})keys.insert(k);
 else for(auto k:{"layerSpacingMeters","plateLengthMeters","thicknessVariation"})keys.insert(k);
 if(j.size()!=keys.size())throw std::invalid_argument("surface recipe requires exactly documented family-specific fields");
 for(auto&[k,v]:j.items())if(!keys.contains(k))throw std::invalid_argument("unknown surface recipe key "+k);
 if(integer(j.at("schemaVersion"),"schemaVersion")!=3||j.at("generatorVersion")!=(reference?"reference-studies-v15":alveolar?"surface-families-v14":"surface-families-v13")||j.at("extractorVersion")!="heightfield-solid-v2"||j.at("family")!="heightfield_cliff"||j.at("units")!="m")throw std::invalid_argument("unsupported surface recipe version or units");
 const auto&g=j.at("grid");if(!g.is_object()||g.size()!=3||!g.contains("cells")||!g.contains("width")||!g.contains("height"))throw std::invalid_argument("surface grid requires cells, width, height");
 auto number=[&](const char*k){if(!j.at(k).is_number())throw std::invalid_argument(std::string(k)+" must be a number");return j.at(k).get<double>();};
 HeightfieldRecipe r;r.profile=profile;r.seed=integer(j.at("seed"),"seed");r.cells=integer(g.at("cells"),"cells");r.width=integer(g.at("width"),"width");r.height=integer(g.at("height"),"height");
 r.size=number("size");r.relief=number("relief");r.backDepth=number("backDepth");r.directionDegrees=number("directionDegrees");r.jointDepth=number("featureDepth");r.fractures=number("fractures");r.irregularity=number("irregularity");
 if(reference){if(lava){r.ridgeSpacingMeters=number("ridgeSpacingMeters");r.ridgeWidthMeters=number("ridgeWidthMeters");r.lobeRadiusMeters=number("lobeRadiusMeters");r.lobeCount=integer(j.at("lobeCount"),"lobeCount");}else{r.fragmentScaleMeters=number("fragmentScaleMeters");r.fragmentCount=integer(j.at("fragmentCount"),"fragmentCount");}}
 else if(alveolar){r.patchCount=integer(j.at("patchCount"),"patchCount");r.patchRadiusMeters=number("patchRadiusMeters");r.alveolusRadiusMeters=number("alveolusRadiusMeters");}
 else if(limestone){r.channelSpacingMeters=number("channelSpacingMeters");r.channelWidthMeters=number("channelWidthMeters");r.pocketRadiusMeters=number("pocketRadiusMeters");r.pocketCount=integer(j.at("pocketCount"),"pocketCount");}
 else{r.layerSpacingMeters=number("layerSpacingMeters");r.plateLengthMeters=number("plateLengthMeters");r.thicknessVariation=number("thicknessVariation");}
 validateHeightfieldRecipe(r);return r;
}
static HeightfieldRecipe parseHeightfield(const json&j){
 if(j.is_object()&&(j.value("generatorVersion",std::string{})=="surface-families-v13"||j.value("generatorVersion",std::string{})=="surface-families-v14"||j.value("generatorVersion",std::string{})=="reference-studies-v15"))return parseSurfaceFamily(j);
 const bool jointed=j.is_object()&&j.value("generatorVersion",std::string{})=="heightfield-cliff-v11";
 const std::set<std::string> keys=jointed?std::set<std::string>{"schemaVersion","generatorVersion","extractorVersion","family","units","seed","size","relief","backDepth","profile","directionDegrees","jointSpacing","jointDepth","blockScale","fractures","irregularity","grid"}:std::set<std::string>{"schemaVersion","generatorVersion","extractorVersion","family","units","seed","size","relief","backDepth","bedCount","thicknessVariation","tiltDegrees","fractures","irregularity","fragmentedContacts","grid"};
 if(!j.is_object()||j.size()!=keys.size())throw std::invalid_argument("heightfield recipe requires exactly documented fields");
 for(auto&[key,value]:j.items())if(!keys.contains(key))throw std::invalid_argument("unknown heightfield key "+key);
 if(integer(j.at("schemaVersion"),"schemaVersion")!=3||(!jointed&&j.at("generatorVersion")!="heightfield-cliff-v10")||j.at("extractorVersion")!="heightfield-solid-v2"||j.at("family")!="heightfield_cliff"||j.at("units")!="m")throw std::invalid_argument("unsupported heightfield version, family or units");
 const auto&g=j.at("grid");if(!g.is_object()||g.size()!=3||!g.contains("cells")||!g.contains("width")||!g.contains("height"))throw std::invalid_argument("heightfield grid requires cells, width, height");
 HeightfieldRecipe r;r.seed=integer(j.at("seed"),"seed");if(!jointed)r.bedCount=integer(j.at("bedCount"),"bedCount");r.cells=integer(g.at("cells"),"cells");r.width=integer(g.at("width"),"width");r.height=integer(g.at("height"),"height");
 auto number=[&](const char*k){if(!j.at(k).is_number())throw std::invalid_argument(std::string(k)+" must be a number");return j.at(k).get<double>();};
 r.size=number("size");r.relief=number("relief");r.backDepth=number("backDepth");if(!jointed){r.thicknessVariation=number("thicknessVariation");r.tiltDegrees=number("tiltDegrees");}r.fractures=number("fractures");r.irregularity=number("irregularity");
 if(jointed){r.profile=j.at("profile").get<std::string>();if(r.profile!="massive_oblique"&&r.profile!="vertical_channels")throw std::invalid_argument("unsupported v11 profile");r.directionDegrees=number("directionDegrees");r.jointSpacing=number("jointSpacing");r.jointDepth=number("jointDepth");r.blockScale=number("blockScale");}
 else{if(!j.at("fragmentedContacts").is_boolean())throw std::invalid_argument("fragmentedContacts must be boolean");r.fragmentedContacts=j.at("fragmentedContacts").get<bool>();}validateHeightfieldRecipe(r);return r;
}
static int generateHeightfieldRecipe(const json&recipe,const fs::path&out){
 auto r=parseHeightfield(recipe);std::optional<AlveolarStudy> study;HeightfieldSamples host,samples;
 if(r.profile=="alveolar_blocks"){study=makeAlveolarStudy(r);host=proceduralHeightfield(alveolarHostRecipe(r));samples=alveolarSamples(r,host,*study);}else samples=proceduralHeightfield(r);auto ex=heightfieldSolid(samples.samples,{r.width,r.height,r.cells,r.size,r.relief,r.backDepth,true});auto report=validate(ex.mesh,r.size);
 json stage={{"accepted",report.accepted},{"vertices",ex.mesh.positions.size()},{"triangles",ex.mesh.indices.size()/3},{"signedVolume",report.signedVolume},{"components",report.components},{"badEdges",report.badEdges},{"badVertices",report.badVertices},{"degenerateFaces",report.degenerateFaces},{"errors",report.errors}};
 json metrics={{"accepted",report.accepted},{"sourceKind","procedural_heightfield"},{"generatorVersion",recipe.at("generatorVersion")},{"profile",r.profile},{"extractorVersion","heightfield-solid-v2"},{"heightMapping","fixed_uint16_0_65535"},{"heightMappingDescription","z = reliefMeters * filteredCode / 65535; no observed min/max normalization"},{"rawScalarMin",samples.rawMin},{"rawScalarMax",samples.rawMax},{"clippedLow",samples.clippedLow},{"clippedHigh",samples.clippedHigh},{"sampleCount",samples.samples.size()},{"sizeMeters",r.size},{"reliefMeters",r.relief},{"backDepthMeters",r.backDepth},{"gridCells",r.cells},{"stageSemantics","heightfield = single-valued procedural front plus closed back/sides; no overhang; no reference pixels"},{"resistanceMeaning","not modeled; constant 0.5 placeholder, hide resistance mode"},{"stages",{{"heightfield",stage}}}};
 if(recipe.at("generatorVersion")=="surface-families-v13"||recipe.at("generatorVersion")=="surface-families-v14"){
  double frontMin=r.relief;for(unsigned i=0;i<(r.cells+1)*(r.cells+1);i++)frontMin=std::min(frontMin,ex.mesh.positions[i].z);
  metrics["imagePixelsUsed"]=false;metrics["geologicalSimulation"]=false;metrics["surfaceModel"]="single_valued_closed_backed_patch";metrics["minimumBackingThicknessMeters"]=r.backDepth+frontMin;metrics["meshCellSpacingMeters"]=r.size/r.cells;metrics["featureUnits"]="meters, with finite seeded layout inside recipe footprint";metrics["scopeLimit"]="Surface grooves, attached plate-edge setbacks and blind hollows only; no detached plates, undercuts, through-pores or cave passages";if(r.profile!="shale_laminated"){auto host=r.profile=="alveolar_blocks"?alveolarHostRecipe(r):surfaceFamilyHostRecipe(r);metrics["baseGeometry"]="inherited_v11_procedural_outcrops";metrics["baseControls"]={{"profile",host.profile},{"directionDegrees",host.directionDegrees},{"blockScale",host.blockScale},{"jointSpacing",host.jointSpacing},{"jointDepth",host.jointDepth},{"fractures",host.fractures},{"irregularity",host.irregularity}};metrics["zeroFeatureDepth"]="exactly preserves the inherited mathematical host samples and extracted geometry";}
 }
 if(isReferenceStudy(r.profile)){metrics["imagePixelsUsed"]=false;metrics["geologicalSimulation"]=false;metrics["baseGeometry"]="new_independent_analytic_evaluator";metrics["scopeLimit"]="Single-valued closed backed relief. Apparent fragments remain attached to matrix; no overhangs or detached stones.";metrics["zeroFeatureDepth"]="low analytic granular matrix only";metrics["referenceRole"]="Human-inspected visual morphology only; no images or textures read by generator";}
 if(!report.accepted){std::cerr<<metrics.dump(2)<<'\n';return 2;}
 fs::create_directories(out);obj(out/"heightfield.obj",ex.mesh);write(out/"recipe.json",recipe);write(out/"metrics.json",metrics);
 if(study){
  json events=json::array();for(const auto&p:study->patches){json cavities=json::array();for(const auto&c:p.cavities)cavities.push_back({{"x",c.x},{"y",c.y},{"radius",c.radius},{"aspect",c.aspect},{"angle",c.angle},{"exponent",c.exponent},{"floor",c.floor},{"amplitude",c.amplitude},{"left",c.left}});events.push_back({{"x",p.x},{"y",p.y},{"radius",p.radius},{"aspect",p.aspect},{"angle",p.angle},{"cavities",cavities}});}
  std::uint64_t changed=0,protectedLeak=0,outsideLeak=0,protectedCount=0,fullMaskCount=0;double removed=0,maxDepth=0;
  for(std::size_t k=0;k<study->guide.mask.size();k++){protectedCount+=study->guide.protectedNodes[k]!=0;fullMaskCount+=study->guide.mask[k]==1;}
  for(unsigned y=0;y<r.height;y++)for(unsigned x=0;x<r.width;x++){auto k=std::size_t(y)*r.width+x;double xx=r.size*(double(x)/(r.width-1)-.5),yy=r.size*(.5-double(y)/(r.height-1)),delta=(double(host.samples[k])-samples.samples[k])*r.relief/65535.;changed+=delta!=0;maxDepth=std::max(maxDepth,delta);protectedLeak+=(delta!=0&&alveolarMaskAt(study->guide,xx,yy)==0);outsideLeak+=(delta!=0&&alveolarCoverage(*study,xx,yy)==0);removed+=delta*(x==0||x+1==r.width?.5:1)*(y==0||y+1==r.height?.5:1);}
  removed*=r.size*r.size/((r.width-1.)*(r.height-1.));
  write(out/"diagnostics.json",{{"guideSide",study->guide.side},{"guideProtectedFraction",double(protectedCount)/study->guide.mask.size()},{"guideFullyEligibleFraction",double(fullMaskCount)/study->guide.mask.size()},{"patchesRequested",r.patchCount},{"patchesAccepted",study->patches.size()},{"changedSourceFraction",double(changed)/samples.samples.size()},{"unchangedSourceFraction",1-double(changed)/samples.samples.size()},{"protectedBandCodeLeakage",protectedLeak},{"outsideCompactSupportCodeLeakage",outsideLeak},{"removedVolumeCubicMeters",removed},{"maximumDepthMeters",maxDepth},{"depthCoefficient",.075},{"events",{{"patches",events}}},{"protectionDomain","bilinear guide mask exactly zero; filtered mesh identity requires zero erosion at every source vertex of every bilinear source cell intersecting the filter box, including vertices outside that box"}});
  std::ofstream guideFile(out/"guide-mask.f64",std::ios::binary);for(double value:study->guide.mask)guideFile.write(reinterpret_cast<const char*>(&value),sizeof(value));if(!guideFile)throw std::runtime_error("cannot export guide mask");
 }
 write(out/"viewer.json",{{"schemaVersion",2},{"sourceKind","procedural_heightfield"},{"domain",{{"min",{-r.size/2,-r.size/2,-r.backDepth}},{"max",{r.size/2,r.size/2,r.relief}}}},{"stages",{{"heightfield",meshjson(ex.mesh)}}}});
 std::ofstream raw(out/"height.u16",std::ios::binary);for(auto value:samples.samples){raw.put(char(value&255));raw.put(char(value>>8));}if(!raw)throw std::runtime_error("cannot export height samples");std::cout<<metrics.dump(2)<<'\n';return 0;
}
int main(int argc,char**argv){try{if(argc>1&&(std::string(argv[1])=="heightmap-reference"||std::string(argv[1])=="procedural-heightfield"))return heightmapCommand(argc,argv);if(argc>1&&std::string(argv[1])=="compare")return compareCommand(argc,argv);if(argc!=6||std::string(argv[1])!="generate"||std::string(argv[2])!="--recipe"||std::string(argv[4])!="--out")throw std::invalid_argument("usage: rocks_cli generate --recipe file --out directory");json recipe=read(argv[3]);if(recipe.is_object()&&recipe.value("schemaVersion",0)==3)return generateHeightfieldRecipe(recipe,argv[5]);unsigned cells;Recipe r=parse(recipe,cells);auto begin=Clock::now();auto f=makeField(r);double prep=std::chrono::duration<double,std::milli>(Clock::now()-begin).count();auto grid=makeGrid(r,cells);std::array<Extraction,3> results;json metrics={{"accepted",true},{"preparationMs",prep},{"seed",r.seed},{"cells",cells},{"generatorVersion",r.generatorVersion},{"extractorVersion",r.extractorVersion},{"coreBufferAccounting","sample + edge-cache + mesh vector capacities; excludes allocator overhead, validation maps, JSON and process RSS"}};if(r.generatorVersion=="rocks-v12"){metrics["sourceKind"]="procedural_volume";metrics["family"]=r.family;metrics["stageSemantics"]="base = parent envelope; stratified = joint-controlled 3D study; eroded = identical structure, no erosion simulation";metrics["resistanceMeaning"]="not modeled; constant 0.5 placeholder";}const char*names[]={"base","stratified","eroded"};
 for(int i=0;i<3;i++){results[i]=r.extractorVersion=="poly-csg-v1"?extractPolyhedral(f,Stage(i)):extract(f,grid,Stage(i));auto t=Clock::now();auto report=validate(results[i].mesh,r.size);double ms=std::chrono::duration<double,std::milli>(Clock::now()-t).count();auto&ex=results[i];bool ok=report.accepted&&!ex.ambiguousCells&&!ex.boundaryTouched;metrics["stages"][names[i]]={{"accepted",ok},{"vertices",ex.mesh.positions.size()},{"triangles",ex.mesh.indices.size()/3},{"signedVolume",report.signedVolume},{"components",report.components},{"degenerateFaces",report.degenerateFaces},{"duplicateFaces",report.duplicateFaces},{"badEdges",report.badEdges},{"badVertices",report.badVertices},{"ambiguousCells",ex.ambiguousCells},{"boundaryTouched",ex.boundaryTouched},{"fieldMs",ex.fieldMs},{"extractNormalsMs",ex.extractNormalsMs},{"validationMs",ms},{"coreBufferBytes",ex.coreBufferBytes},{"surfaceDetailMs",ex.surfaceDetailMs},{"maxDisplacement",ex.maxDisplacement},{"jacobianLowerBound",ex.jacobianLowerBound},{"flippedTriangles",ex.flippedTriangles},{"preservedSharpVertices",ex.preservedSharpVertices},{"contractedEdges",ex.contractedEdges},{"contractedFaces",ex.contractedFaces},{"maxContractionDistance",ex.maxContractionDistance},{"errors",report.errors}};if(r.extractorVersion=="poly-csg-v1")metrics["stages"][names[i]]["ambiguousCells"]=nullptr;if(!ok){std::cerr<<names[i]<<": "<<metrics["stages"][names[i]].dump()<<'\n';return 2;}}
 fs::path out=argv[5];fs::create_directories(out);auto t=Clock::now();json transport={{"schemaVersion",1},{"domain",{{"min",{grid.min.x,grid.min.y,grid.min.z}},{"max",{grid.max.x,grid.max.y,grid.max.z}}}}};for(int i=0;i<3;i++){transport["stages"][names[i]]=meshjson(results[i].mesh);obj(out/(std::string(names[i])+".obj"),results[i].mesh);}write(out/"viewer.json",transport);write(out/"recipe.json",recipe);metrics["serializationMs"]=std::chrono::duration<double,std::milli>(Clock::now()-t).count();if(r.extractorVersion=="poly-csg-v1"){metrics["coreBufferAccounting"]="accounted mesh and planar polygon vector capacities, excluding map/allocator overhead; not RSS or certified peak";metrics["gridUsedForExtraction"]=false;if(r.generatorVersion!="rocks-v12")metrics["stageSemantics"]="base=macro mass; stratified=structural fractures; eroded identical because wear0 (curved wear unsupported on direct route)";}write(out/"metrics.json",metrics);std::cout<<metrics.dump(2)<<'\n';return 0;
 }catch(const json::exception&e){std::cerr<<"invalid JSON/recipe: "<<e.what()<<'\n';return 2;}catch(const std::invalid_argument&e){std::cerr<<e.what()<<'\n';return 2;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
